<?php use App\Core\Csrf; ?>
<div class="page-heading"><div><p class="eyebrow">Inventory assignment</p><h1>Issue inventory item</h1><p>Assign a uniform, ID card, or other available stock to a student, teacher, or employee.</p></div><a class="button" href="<?=e(url('/uniform-id'))?>">Cancel</a></div>
<?php if(!$items):?><div class="alert danger">No items currently have available stock. Add or receive stock before issuing.</div><?php endif;?>
<form class="card form-section stack-form inventory-form" method="post" action="<?=e(url('/uniform-id/issue'))?>"><?=Csrf::field()?><label>Inventory item<select required name="inventory_item_id"><option value="">Select available stock</option><?php foreach($items as $item):?><option value="<?=$item['id']?>"><?=e($item['sku'].' — '.$item['name'].($item['variant']?' · '.$item['variant']:'').' ('.$item['quantity_on_hand'].' available)')?></option><?php endforeach;?></select></label><div class="grid two"><label>Recipient type<select required name="recipient_type" id="recipient-type"><option value="student">Student</option><option value="teacher">Teacher</option><option value="employee">Employee</option></select></label><label>Recipient<select required name="recipient_id" id="recipient-id"><?php foreach(['student'=>$students,'teacher'=>$teachers,'employee'=>$employees] as $kind=>$people):?><?php foreach($people as $person):?><option data-kind="<?=$kind?>" value="<?=$person['id']?>"><?=e($person['last_name'].', '.$person['first_name'].' ('.($person['student_no']??$person['employee_no']).')')?></option><?php endforeach;?><?php endforeach;?></select></label><label>Quantity<input required type="number" min="1" name="quantity" value="1"></label><label>Issue date<input required type="date" name="issued_on" value="<?=date('Y-m-d')?>"></label></div><label>Notes<textarea name="notes" rows="3" placeholder="Purpose, acknowledgement, or reference"></textarea></label><button class="button primary" <?=$items?'':'disabled'?>>Issue and reduce inventory</button></form>
<script>const type=document.getElementById('recipient-type'),recipient=document.getElementById('recipient-id'),options=[...recipient.options].map(x=>x.cloneNode(true));function recipients(){const selected=recipient.value;recipient.replaceChildren(...options.filter(x=>x.dataset.kind===type.value).map(x=>x.cloneNode(true)));if([...recipient.options].some(x=>x.value===selected))recipient.value=selected;}type.addEventListener('change',recipients);recipients();</script>
